'use cilent'
import Navbar from "@/components/Navbar";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { useState, useEffect } from "react";

export default async function AdminLogsPage() {
    // Server-side check
    const cookieStore = cookies();
    const token = (await cookieStore).get("admin_token")?.value;
    if (!token) redirect("/login");

    return <LogsPageClient token={token} />;
}

// Client-side component to fetch logs
function LogsPageClient({ token }: { token: string }) {
    const [logs, setLogs] = useState<string[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");

    useEffect(() => {
        const fetchLogs = async () => {
            try {
                const res = await fetch("/api/admin/logs", {
                    headers: { cookie: `admin_token=${token}` },
                });
                if (!res.ok) throw new Error("Failed to fetch logs");
                const data = await res.json();
                setLogs(data.logs || []);
            } catch (err: any) {
                setError(err.message);
            } finally {
                setLoading(false);
            }
        };
        fetchLogs();
    }, [token]);

    return (
        <div className="min-h-screen bg-gray-50">
            <Navbar />
            <div className="max-w-7xl mx-auto px-6 py-10">
                <h1 className="text-3xl font-semibold text-gray-800 mb-8">
                    Server Logs
                </h1>

                {loading && <p className="text-gray-600">Loading logs...</p>}
                {error && <p className="text-red-500">{error}</p>}

                {!loading && !error && (
                    <div className="bg-white shadow-sm rounded-xl border border-gray-200 overflow-auto max-h-[70vh]">
                        <ul className="p-4 font-mono text-xs text-gray-700 space-y-2">
                            {logs.length === 0 && <li>No logs found.</li>}
                            {logs.map((line, i) => (
                                <li key={i}>{line}</li>
                            ))}
                        </ul>
                    </div>
                )}
            </div>
        </div>
    );
}